import{_ as s,c as t,o as n,j as e,a as r}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"爻象第十二","description":"杭氏易學 - 爻象第十二","frontmatter":{"title":"爻象第十二","description":"杭氏易學 - 爻象第十二"},"headers":[],"relativePath":"classics/hangshi/013.md","filePath":"classics/hangshi/013.md"}'),l={name:"classics/hangshi/013.md"};function i(c,a,o,d,p,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"爻象第十二",tabindex:"-1"},[r("爻象第十二 "),e("a",{class:"header-anchor",href:"#爻象第十二","aria-label":"Permalink to “爻象第十二”"},"​")],-1),e("p",null,"爻分於卦，卦之象即爻之象。卦由爻變，爻之象亦卦之變象也。《說卦》廣象，半為卦變言之。名隸於卦，而重實在爻。六十四卦，《彖》、《象》要皆以象之交易變易反易而互變其義，以定其辭。變之所在，即象之所在。所謂“辭也者，各指其所之”是也。變不同，象亦不同。或一爻變，或二爻變，或三爻變。三爻變者，則為對象。以一卦全變，本體之象已不見，所謂伏也。若二爻或一爻變，則變其半而存其半，京氏所以有半象之說也。向來講《易》者莫明京氏半象之義，往往置之不論。焦理堂氏《易通釋》宗虞仲翔氏之說者也，乃駁其半象，不遺餘力。謂“坎之半即巽之半，坤之半即艮之半”云云，而不知京說之正謂“坎半即巽半，坤半即艮半”耳。孔子《雜卦》，“震起艮止，巽伏兌見”，即發明離坎變化，乃震艮巽兌起止伏見之作用。《虞注》：“小畜密雲不雨，謂坎象半見。”即指巽為坎之半耳。惟半象二字，在可解不可解之間。與其謂之半象，不如名之曰爻象為簡當而易曉也。一卦六爻，本有風雷山澤水火之爻位。與八卦之正位，有其位即有其象。故僅知卦象，而不明爻象，仍未能盡象義之蘊也。",-1),e("p",null,"爻象有正變之分，亦與卦同。如本卦不變，而分爻取象者，則以其位之上下而象異。如震為足，正象也，爻分震之初則為趾。乾為首，正象也，爻分乾之上則為顛，為額，或為項。而六子分乾坤之爻者，亦得推此義以取象。如艮為乾之上爻，亦有首之象。離得坤之中爻，亦取腹象。此不變之變，即廣象之義也。",-1),e("p",null,"其因本卦已變，而爻即隨其變而易其象，則必以其時其位之不同，而各異其義，即各異其象。如離為目，正象也，因變巽而為多白眼。艮為山，正象也，因反為震，而變為陵。巽為雞，正象也，因反為兌，而稱鶴。其餘變化，各以類求，未可指數也。",-1),e("p",null,"一卦六爻，初爻為足為趾；二爻為脛，為股；三四為心，為腹；上五為首，為面。比例甚多，更論爻而不論卦，可謂專以爻位取象，為爻象之本義矣。",-1)])])}const f=s(l,[["render",i]]);export{_ as __pageData,f as default};
